questionvariables.text:
/* 3次行列式の線形性1 */
/* v004 : 可変行列解答 (2023.8.5) */
/* v003 : 説明と全体フィードバック (2023.6.11) */
stack_include("https://stack.mathedu.jp/sc/ky_linear_algebra.mac");
sz:3;
n:sz;
matE3:genmatrix(lambda([i, j],  if i=j then 1 else 0), 3, 3);
aL1:append(makelist(-i, i, 2), makelist(i, i, 2));
aL2:append(makelist(-i, i, 5), makelist(i, i, 5));
matA1:genmatrix(lambda([i, j], rand(aL2)), n, n);
a:rand_with_prohib(-4, 4, [0, 1]);
j2:rand([1, 2, 3]);
jX2:listify(setdifference({1, 2, 3}, {j2}));
matA2:genmatrix(lambda([i, j], if j=j2 then rand(aL2) else matA1[i, j]), n, n);
matA:genmatrix(lambda([i, j], if j=j2 then matA1[i, j]+matA2[i, j] else matA1[i, j]), n, n);
dt:determinant(matA);
dt1:determinant(matA1);
dt2:determinant(matA2);
ta1:transpose(matrix(makelist(matA2[i, j2], i, 1, 3)));
Cans1:ta1;
matA2[1, j2]:p;matA2[2, j2]:q;matA2[3, j2]:r;
MtoTeX(M):=block([m, n, i, j, s], s:"\\begin{vmatrix}", [m, n]:matrix_size(M), for i:1 thru m do (for j:1 thru n do (s:sconcat(s, M[i, j]), if j<n then s:sconcat(s, "&")), if i<m then s:sconcat(s, "\\\\")), return(sconcat(s, "\\end{vmatrix}")));
vmat(M):=block([_lc:lmxchar, s], lmxchar:"|", s:tex1(M), lmxchar:_lc, return(s));
dA:vmat(matA);
dA1:vmat(matA1);
dA2:vmat(matA2);

feedbackvariables.text:
matB2:genmatrix(lambda([i,j], if j=j2 then ans1[i,1] else matA2[i,j]),n,n);
chk1:is(determinant(matA)=determinant(matA1)+determinant(matB2));
dt1S:sconcat("",dt1,"");
dt2S:if dt2 < 0 then sconcat("(",dt2,")") else sconcat("",dt2,"");
